INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Läuft eine For-Schleife immer eine feste Anzahl an Durchläufen?', 2, '[{"text": "Ja", "correct": true, "because": "Zähler definiert Iterationen"}, {"text": "Nein", "correct": false, "because": "Nur bei Break änderbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer For-Schleife?', 3, '[{"text": "Wiederholte Ausführung mit Zähler", "correct": true, "because": "Steuert Iterationen"}, {"text": "Einmalige Bedingungsprüfung", "correct": false, "because": "Für If geeignet"}, {"text": "UI-Anpassung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile hat eine For-Schleife?', 5, '[{"text": "Initialisierung", "correct": true, "because": "Setzt Startwert"}, {"text": "Bedingung", "correct": true, "because": "Prüft Fortsetzung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}, {"text": "Datenbankzugriff", "correct": false, "because": "Kein Kernbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) For-Schleifen brauchen einen Zähler. b) Sie sind immer endlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Endlos nur bei Fehlern"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung einer For-Schleife?', 4, '[{"text": "Iterationsgrenze", "correct": false, "because": "Definiert Ende"}, {"text": "Zählerinkrement", "correct": false, "because": "Steuert Fortschritt"}, {"text": "Serverkonfiguration", "correct": true, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob For-Schleifen nur für Arrays sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Bereiche nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Syntax wähle ich für eine For-Schleife in Python?', 3, '[{"text": "for i in range(5)", "correct": true, "because": "Iteriert über Bereich"}, {"text": "while i < 5", "correct": false, "because": "While-Schleife"}, {"text": "if i == 5", "correct": false, "because": "Bedingung, keine Schleife"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine For-Schleife?', 5, '[{"text": "Kontrolle über Iterationen", "correct": true, "because": "Zähler steuerbar"}, {"text": "Einfache Struktur", "correct": true, "because": "Klar definierbar"}, {"text": "Dynamische Anpassung", "correct": false, "because": "Feste Grenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) For-Schleifen sind effizient. b) Sie brauchen immer manuelle Steuerung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist automatisiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine For-Schleife?', 4, '[{"text": "Startwert", "correct": false, "because": "Definiert Anfang"}, {"text": "Bedingung", "correct": false, "because": "Steuert Ende"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine For-Schleife endlos laufen?', 2, '[{"text": "Ja", "correct": true, "because": "Bei fehlender Grenze"}, {"text": "Nein", "correct": false, "because": "Nur bei falscher Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Steuerungsmöglichkeiten habe ich in einer For-Schleife?', 4, '[{"text": "Break", "correct": true, "because": "Beendet Schleife"}, {"text": "Continue", "correct": true, "because": "Überspringt Iteration"}, {"text": "Push", "correct": false, "because": "Git-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass For-Schleifen nur für Zahlen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Listen nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer For-Schleife?', 3, '[{"text": "Klar definierte Grenzen", "correct": true, "because": "Verhindert Endlosschleifen"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) For-Schleifen haben feste Iterationen. b) Sie sind für Bedingungen besser als While.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei einer For-Schleife?', 5, '[{"text": "Endlosschleifen", "correct": true, "because": "Bei falscher Grenze"}, {"text": "Leistungsprobleme", "correct": true, "because": "Bei großen Iterationen"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer For-Schleife unwichtig?', 3, '[{"text": "Zähler", "correct": false, "because": "Steuert Iteration"}, {"text": "Bedingung", "correct": false, "because": "Definiert Ende"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich eine For-Schleife ohne Zähler nutzen?', 3, '[{"text": "Ja", "correct": true, "because": "In manchen Sprachen wie Python"}, {"text": "Nein", "correct": false, "because": "Sprachabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob For-Schleifen immer inkrementieren?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch dekrementieren"}, {"text": "Ja", "correct": false, "because": "Flexibel steuerbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um eine Iteration zu überspringen?', 4, '[{"text": "continue", "correct": true, "because": "Springt zur nächsten Iteration"}, {"text": "break", "correct": false, "because": "Beendet Schleife"}, {"text": "return", "correct": false, "because": "Verlässt Funktion"}]');
